import {experimentalManifest} from "./experimental-features.js";
import {TelemetryOutbox} from "./telemetry-outbox.js";
const n=x=>Number.isFinite(Number(x))?Number(x):0,mono=()=>typeof performance!=="undefined"&&performance.now?performance.now():Date.now(),uid=prefix=>prefix+"-"+Date.now().toString(36)+"-"+Math.random().toString(36).slice(2,10);
function mismatchNorm(r){const m=r?.motorMismatch||[0,0,0];return Math.hypot(n(m[0]),n(m[1]),n(m[2]));}
function vectorDrift(a,b){if(!Array.isArray(a)||!Array.isArray(b)||a.length!==b.length)return 0;let s=0;for(let i=0;i<a.length;i++){const d=n(b[i])-n(a[i]);s+=d*d;}return Math.sqrt(s/Math.max(1,a.length));}
function maxLocalForce(r){let m=0;for(const s of(r?.localSides||[]))m=Math.max(m,n(s.push),n(s.pull));return m;}
function triggerOf(r){if(!r)return null;if(!r.accepted&&r.confidence>=.65)return"CONFIDENT_REJECT";if(mismatchNorm(r)>=.55)return"HIGH_MOTOR_MISMATCH";if(maxLocalForce(r)>=.75)return"HIGH_LOCAL_FORCE";if(vectorDrift(r.zSelfBefore,r.zSelfAfter)>=.18)return"Z_SELF_JUMP";if(n(r.localReward?.milestone)>0)return"MILESTONE";if(n(r.localReward?.terminal)>0)return"TERMINAL";if(n(r.energy?.debt)>.05)return"ENERGY_DEBT";if(Math.abs(n(r.pendingRewardConsumed))>=6)return"LARGE_PENDING_REWARD";return null;}
function signature(r,tr){return[tr,r.action,r.reason,r.localReward?.zone,Math.round(mismatchNorm(r)*4)/4].join("|");}
function compactRecord(r){return{globalStep:r.globalStep,cycle:r.cycle,ego:r.ego,cellUid:r.cellUid,specialistId:r.specialistId,obs:r.obs,zSelfBefore:r.zSelfBefore,zSelfAfter:r.zSelfAfter,probs:r.probs,action:r.action,confidence:r.confidence,value:r.value,entropy:r.entropy,higherContext:r.higherContext,pendingRewardConsumed:r.pendingRewardConsumed,accepted:r.accepted,reason:r.reason,actual:r.actual,motorMismatch:r.motorMismatch,localSides:r.localSides,localReward:r.localReward,energy:r.energy,n:r.n,k:r.k,perspectiveD:r.perspectiveD,spatial:r.spatial,cortical:r.cortical,positions:r.positions};}
function makeWindow(byEgo,group,batch,ego,trigger,sig,centerIndex){const own=byEgo[ego]||[],lo=Math.max(0,centerIndex-32),hi=Math.min(own.length,centerIndex+33),window=own.slice(lo,hi);if(!window.length)return null;const minStep=window[0].globalStep,maxStep=window.at(-1).globalStep,neighborIds=new Set();for(const r of window)for(const s of(r.localSides||[]))if(s.contact&&Number.isInteger(s.neighborId))neighborIds.add(s.neighborId);const neighbors={};for(const id of neighborIds)neighbors[id]=(byEgo[id]||[]).filter(r=>r.globalStep>=minStep&&r.globalStep<=maxStep).map(compactRecord);return{group,batch,targetEgo:ego,trigger,signature:sig||null,centerGlobalStep:own[centerIndex].globalStep,records:window.map(compactRecord),neighbors};}
export function buildInterrogationBundle(trace,group,batch,maxWindows=4){if(!Array.isArray(trace)||!trace.length)return{group,batch,periodic:[],anomalies:[]};const maxEgo=trace.reduce((m,r)=>Math.max(m,Number(r?.ego)||0),0),byEgo=Array.from({length:maxEgo+1},()=>[]);for(const r of trace)if(r&&r.ego>=0&&r.ego<byEgo.length)byEgo[r.ego].push(r);const anomalies=[],seen=new Map();for(let ego=0;ego<byEgo.length;ego++){const a=byEgo[ego];for(let i=0;i<a.length;i++){const tr=triggerOf(a[i]);if(!tr)continue;const sig=signature(a[i],tr),count=seen.get(sig)||0;if(count>=3)continue;seen.set(sig,count+1);const p=makeWindow(byEgo,group,batch,ego,"anomaly:"+tr,sig,i);if(p)anomalies.push(p);if(anomalies.length>=maxWindows)break;}if(anomalies.length>=maxWindows)break;}const target=byEgo.length?batch%byEgo.length:0,a=byEgo[target],periodic=[];if(a?.length){const p=makeWindow(byEgo,group,batch,target,"periodic",null,Math.floor(a.length/2));if(p)periodic.push(p);}return{group,batch,periodic,anomalies};}
export class TelemetryClient{
  constructor(){this.campaignId="octopus-v9-vectric4v8-qanda-brsi1-"+new Date().toISOString().replace(/[:.]/g,"-");this.sessionId=uid("session");this.sequence=0;this.enabled=true;this.failedPosts=0;this.outbox=new TelemetryOutbox();this.flushing=false;this.stats={posts:0,success:0,failed:0,outboxEvicted:0,forcedProtectedEvictions:0};}
  envelope(kind,payload={}){return{kind,campaignId:this.campaignId,sessionId:this.sessionId,eventSeq:++this.sequence,clientTime:new Date().toISOString(),monotonicMs:mono(),...payload};}
  async _store(body,json){try{const q=await this.outbox.enqueue(body,json);this.stats.outboxEvicted+=q.evicted?.length||0;this.stats.forcedProtectedEvictions+=q.forcedProtectedEvictions||0;return q;}catch(e){console.warn("telemetry outbox persistence failed",e);return null;}}
  async flushOutbox(){if(this.flushing||!this.enabled)return;this.flushing=true;try{const all=await this.outbox.all();for(const rec of all.slice(0,16)){try{const r=await fetch("/telemetry",{method:"POST",headers:{"Content-Type":"application/json"},body:rec.json});if(!r.ok)break;await this.outbox.remove(rec.id);}catch(_){break;}}}finally{this.flushing=false;}}
  async post(kind,payload={}){if(!this.enabled)return null;const body=this.envelope(kind,payload),json=JSON.stringify(body);this.stats.posts++;try{const r=await fetch("/telemetry",{method:"POST",headers:{"Content-Type":"application/json"},body:json,keepalive:kind==="clean_shutdown"});if(!r.ok)throw new Error("telemetry HTTP "+r.status);this.stats.success++;this.failedPosts=0;void this.flushOutbox();return await r.json();}catch(e){this.stats.failed++;this.failedPosts++;await this._store(body,json);console.warn("telemetry queued after failure:",e);return null;}}
  sessionStart(meta={}){return this.post("session_start",{schemaVersion:7,architectureVersion:"v9-vectric4v8-qanda-brsi1",...meta});}
  heartbeat(snapshot={},eventLoopLagMs=0){return this.post("heartbeat",{schemaVersion:7,eventLoopLagMs:n(eventLoopLagMs),snapshot});}
  runtimeEvent(type,payload={}){return this.post("runtime_event",{schemaVersion:7,type,...payload});}
  cleanShutdown(reason="pagehide"){return this.post("clean_shutdown",{schemaVersion:7,reason});}
  sendCleanShutdownBeacon(reason="pagehide"){if(typeof navigator==="undefined"||typeof navigator.sendBeacon!=="function")return false;const body=this.envelope("clean_shutdown",{schemaVersion:7,reason});try{return navigator.sendBeacon("/telemetry",new Blob([JSON.stringify(body)],{type:"application/json"}));}catch(_){return false;}}
  interrogation({group,batch,policyVersion,envId=0,targetEgo=0,trigger="periodic",requestId=null,signature=null,records=[],neighbors={},severity=null,complete=true}={}){return this.post("v9_vectric4v8_qanda_brsi1_interrogation",{schemaVersion:7,group,batch,policyVersion,envId,targetEgo,trigger,requestId,signature,severity,complete,window:{records,neighbors},cellStatsCount:0,cellStats:[]});}
  async batch(trainer,result){const gr=trainer.groupRuntime||null,activeGroups=gr?.groups?Object.entries(gr.groups).filter(([,q])=>q?.targetEnabled!==false).map(([g])=>g):["A","B"];const payload={schemaVersion:7,batch:trainer.batch,stage:trainer.stage,policyVersion:trainer.policyVersion,trainingGroup:result?.group||result?.row?.trainingGroup||null,activeGroups,groupRuntime:gr?structuredClone(gr):null,config:{stepsPerEgoTurn:trainer.config.stepsPerEgoTurn,egoDecisionHz:trainer.config.egoDecisionHz,groupASimulationCount:trainer.config.groupASimulationCount,groupBSimulationCount:trainer.config.groupBSimulationCount,workerThreadCount:trainer.config.workerThreadCount,maxGlobalActions:trainer.config.maxGlobalActions,energyBaseAtN16:trainer.config.energyBaseAtN16,energyRewardScale:trainer.config.energyRewardScale,experimental:experimentalManifest(trainer.config)},metrics:result.row},jobs=[this.post("v9_vectric4v8_qanda_brsi1_batch_summary",payload)];for(const [group,trace] of [["A",result.traceA],["B",result.traceB]]){const q=buildInterrogationBundle(trace,group,trainer.batch);for(const p of [...q.periodic,...q.anomalies])jobs.push(this.interrogation({group,batch:trainer.batch,policyVersion:trainer.policyVersion,targetEgo:p.targetEgo,trigger:p.trigger,signature:p.signature,records:p.records,neighbors:p.neighbors}));}return Promise.allSettled(jobs);}
  async summary(){const q=await this.outbox.summary().catch(()=>({count:-1,bytes:-1,protected:-1}));return{campaignId:this.campaignId,sessionId:this.sessionId,eventSeq:this.sequence,failedPosts:this.failedPosts,stats:{...this.stats},outbox:q};}
}
